<?php

namespace App\Services\Announcement;

use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

/**
 * Chunked video upload, ported from the proven implementation in the
 * sibling `new-courses` project (app/Services/Video/VideoChunkUploadService.php),
 * then reshaped after manager feedback (2026-11-20) to match the pattern
 * used in the sibling ScreensPizza project: the upload UUID is generated by
 * the backend in initUpload(), never by the frontend — the client only ever
 * echoes back the id this service handed it. Per-upload state (total
 * chunks/size, filename, and any video metadata reported so far) lives in a
 * meta.json file alongside the chunks, not in the request.
 *
 * Uses the existing 'local' (private) and 'public' disks — no dedicated
 * filesystem config — namespaced under an `announcement-chunks/` /
 * `announcements/` subfolder respectively.
 */
class AnnouncementVideoChunkUploadService
{
    private const CHUNKS_DISK = 'local';
    private const CHUNKS_PREFIX = 'announcement-chunks/chunks';
    private const MEDIA_DISK = 'public';
    private const MEDIA_PREFIX = 'announcements/media';
    private const ALLOWED_EXTENSIONS = ['mp4', 'mov', 'webm'];

    public function __construct(
        private readonly AnnouncementMediaService $mediaService,
    ) {
    }

    private function maxVideoBytes(): int
    {
        return (int) config('services.announcements.max_video_bytes');
    }

    private function chunkDir(string $uuid): string
    {
        return self::CHUNKS_PREFIX.'/'.$uuid;
    }

    private function metaPath(string $uuid): string
    {
        return $this->chunkDir($uuid).'/meta.json';
    }

    /**
     * Rejects an oversized or unsupported upload before a UUID even exists
     * — nothing is ever stored for it, not even a chunk 0.
     */
    public function initUpload(int $totalChunks, int $totalSize, string $originalFilename): array
    {
        if ($totalSize > $this->maxVideoBytes()) {
            throw ValidationException::withMessages([
                'total_size' => 'Video exceeds the '.$this->maxVideoBytes().'-byte limit ('.$totalSize.' bytes declared). Upload rejected before it was accepted.',
            ]);
        }

        $extension = strtolower(pathinfo($originalFilename, PATHINFO_EXTENSION) ?: '');

        if (!in_array($extension, self::ALLOWED_EXTENSIONS, true)) {
            throw ValidationException::withMessages([
                'original_filename' => 'Unsupported video format: '.$extension,
            ]);
        }

        $uuid = (string) Str::uuid();

        Storage::disk(self::CHUNKS_DISK)->put($this->metaPath($uuid), json_encode([
            'total_chunks' => $totalChunks,
            'total_size' => $totalSize,
            'original_filename' => $originalFilename,
            'width' => null,
            'height' => null,
            'duration_seconds' => null,
        ]));

        return [
            'upload_uuid' => $uuid,
            'total_chunks' => $totalChunks,
        ];
    }

    private function readMeta(string $uuid): array
    {
        $disk = Storage::disk(self::CHUNKS_DISK);
        $path = $this->metaPath($uuid);

        if (!$disk->exists($path)) {
            throw ValidationException::withMessages([
                'upload_uuid' => 'Unknown or expired upload. Call the init endpoint first.',
            ]);
        }

        return json_decode($disk->get($path), true);
    }

    /** @return array<int, string> chunk file paths, meta.json excluded */
    private function chunkFiles(string $uuid): array
    {
        return array_values(array_filter(
            Storage::disk(self::CHUNKS_DISK)->files($this->chunkDir($uuid)),
            fn (string $f) => !str_ends_with($f, 'meta.json'),
        ));
    }

    public function uploadChunk(
        UploadedFile $chunk,
        string $uuid,
        int $index,
        ?int $width = null,
        ?int $height = null,
        ?int $durationSeconds = null,
    ): array {
        $disk = Storage::disk(self::CHUNKS_DISK);
        $meta = $this->readMeta($uuid);
        $dir = $this->chunkDir($uuid);

        if ($width !== null || $height !== null || $durationSeconds !== null) {
            $meta['width'] = $width ?? $meta['width'];
            $meta['height'] = $height ?? $meta['height'];
            $meta['duration_seconds'] = $durationSeconds ?? $meta['duration_seconds'];
            $disk->put($this->metaPath($uuid), json_encode($meta));
        }

        $disk->put("{$dir}/chunk_{$index}", file_get_contents($chunk->getRealPath()));

        $chunkFiles = $this->chunkFiles($uuid);
        $receivedBytes = array_sum(array_map(fn (string $f) => $disk->size($f), $chunkFiles));

        // Checked as chunks arrive, not only after the final merge: an
        // oversized upload is rejected — and its temp chunks deleted —
        // as soon as the running total crosses the limit. initUpload()
        // already rejects based on the declared total_size; this is the
        // safety net against a client that sends more than it declared.
        if ($receivedBytes > $this->maxVideoBytes()) {
            $disk->deleteDirectory($dir);

            throw ValidationException::withMessages([
                'chunk' => 'Video exceeds the '.$this->maxVideoBytes().'-byte limit ('.$receivedBytes.' bytes received so far). Upload stopped.',
            ]);
        }

        $received = count($chunkFiles);
        $total = (int) $meta['total_chunks'];

        if ($received >= $total) {
            return $this->finalize($uuid, $meta);
        }

        return [
            'status' => 'pending',
            'received' => $received,
            'total' => $total,
        ];
    }

    public function finalize(string $uuid, array $meta): array
    {
        $dir = $this->chunkDir($uuid);
        $total = (int) $meta['total_chunks'];
        $files = $this->chunkFiles($uuid);

        if (count($files) < $total) {
            throw ValidationException::withMessages([
                'chunk' => "Upload incomplete: expected {$total} chunks, received ".count($files).'.',
            ]);
        }

        $extension = strtolower(pathinfo($meta['original_filename'], PATHINFO_EXTENSION) ?: 'mp4');
        $destinationName = $uuid.'.'.$extension;
        $destinationRelative = self::MEDIA_PREFIX.'/'.$destinationName;
        $destPath = Storage::disk(self::MEDIA_DISK)->path($destinationRelative);
        $destDir = dirname($destPath);

        if (!is_dir($destDir)) {
            mkdir($destDir, 0755, true);
        }

        $out = fopen($destPath, 'wb');

        for ($i = 0; $i < $total; $i++) {
            $chunkPath = Storage::disk(self::CHUNKS_DISK)->path("{$dir}/chunk_{$i}");

            if (!file_exists($chunkPath)) {
                fclose($out);
                Storage::disk(self::MEDIA_DISK)->delete($destinationRelative);

                throw ValidationException::withMessages([
                    'chunk' => "Chunk {$i} is missing. Cannot finalize upload.",
                ]);
            }

            $in = fopen($chunkPath, 'rb');
            stream_copy_to_stream($in, $out);
            fclose($in);
        }

        fclose($out);

        $fileSize = filesize($destPath);

        Storage::disk(self::CHUNKS_DISK)->deleteDirectory($dir);

        // Defense in depth only — initUpload() already rejects based on the
        // declared size, and uploadChunk() rejects as bytes arrive. This
        // just guards against both somehow being bypassed.
        if ($fileSize > $this->maxVideoBytes()) {
            Storage::disk(self::MEDIA_DISK)->delete($destinationRelative);

            throw ValidationException::withMessages([
                'chunk' => 'Video exceeds the '.$this->maxVideoBytes().'-byte limit once reassembled ('.$fileSize.' bytes).',
            ]);
        }

        return [
            'status' => 'complete',
            'media_path' => $destinationRelative,
            'media_url' => $this->mediaService->toUrl($destinationRelative),
            'media_type' => 'video',
            'file_size' => $fileSize,
            'width' => $meta['width'] ?? null,
            'height' => $meta['height'] ?? null,
            'duration_seconds' => $meta['duration_seconds'] ?? null,
        ];
    }

    public function revert(string $uuid): void
    {
        if (!Str::isUuid($uuid)) {
            return;
        }

        Storage::disk(self::CHUNKS_DISK)->deleteDirectory($this->chunkDir($uuid));
    }
}
